(function(G){'use strict';
// One title template for the generated first paint and the profile-aware application.
function scene(art){return `<picture class="title-painting"><source media="(orientation: portrait)" type="image/webp" srcset="${art.portrait}"><source media="(orientation: portrait)" type="image/jpeg" srcset="${art.portraitFallback}"><source type="image/webp" srcset="${art.landscape}"><img src="${art.landscapeFallback}" alt="" decoding="async" fetchpriority="high" onerror="this.hidden=true"></picture>`;}
function actions({profile,debugMode=false,splitLocked=false,loading=false}={}){if(loading)return '<div class="title-actions"><button class="primary" type="button" data-startup-start aria-disabled="true">준비 중</button></div>';const restart=!!profile.honroMapRestart,resumeRest=!restart&&!!profile.honroJourney?.story;return `<div class="title-actions"><button class="primary" data-action="${restart?'continue':resumeRest?'rest':profile.honroBattle ? 'continue' : 'rest'}">${restart?'새 지형에서 다시 걷기':resumeRest?'쉼터 대화 이어가기':profile.honroBattle ? '이어서 걷기' : Object.keys(profile.cleared).length ? '여정 이어가기' : '길을 열다'}</button>${profile.honroBattle ? resumeRest?'<button class="ghost" data-action="continue">저장된 전투 이어서 걷기</button>':!debugMode&&splitLocked?'':'<button class="ghost" data-action="rest">길 위의 쉼터</button>' : ''}</div>`;}
function render(options){const {scene='',logo='',hanja='',debugMode=false,settingsIcon='',loading=false}=options;return `<main class="screen title honro-title"${loading?' data-startup-title aria-busy="true"':''}><div class="title-bg" aria-hidden="true">${scene||""}</div><header class="top">${debugMode?'<span class="debug-badge">디버그 · 기록 분리</span>':''}<span class="grow"></span><button class="icon ghost" data-action="settings" aria-label="설정"${loading?' disabled':''}>${settingsIcon}</button></header><input type="file" id="map-import" accept=".json" hidden><section class="title-main"><div class="honro-logo-wrap"><h1 class="title-brand" aria-label="혼로"><svg class="title-ink-defs" width="0" height="0" aria-hidden="true" focusable="false"><defs><filter id="honro-title-ink" x="-1%" y="-1%" width="111%" height="102%" primitiveUnits="objectBoundingBox" color-interpolation-filters="sRGB"><feTurbulence type="fractalNoise" baseFrequency="12 9" numOctaves="3" seed="13" result="weathered"/><feColorMatrix in="weathered" type="matrix" values=".6 0 0 0 .17 .6 0 0 0 .185 .58 0 0 0 .18 0 0 0 0 1"/><feComposite in2="SourceGraphic" operator="in"/></filter></defs></svg><span class="title-hanja" aria-hidden="true">${hanja?`<img class="honro-logo honro-logo-hanja" src="${hanja}" alt="" width="1859" height="846" onerror="this.hidden=true;this.nextElementSibling.hidden=false"><span class="title-logo-fallback" hidden>魂路</span>`:'<span class="title-logo-fallback">魂路</span>'}</span><span class="title-hangul" aria-hidden="true">${["혼","로"].map((syllable,i)=>`<span class="title-reading-glyph title-reading-glyph-${i}">${logo?`<img class="honro-logo honro-logo-hangul" src="${logo}" alt="" width="1100" height="550" onerror="this.hidden=true;this.nextElementSibling.hidden=false"><span class="title-reading-fallback" hidden>${syllable}</span>`:`<span class="title-reading-fallback">${syllable}</span>`}</span>`).join("")}</span></h1></div><p class="title-tagline">떠나지 못한 이들을 위한 길.</p>${actions(options)}</section><footer class="footer"><button class="ghost" data-action="import-map"${loading?' disabled':''}>Workshop Map</button><span class="grow"></span><span>연목의 매듭 · 울리지 않는 종</span></footer></main>`;}
function mount(host,options){const title=host.querySelector('[data-startup-title]');if(title){title.querySelector('.title-actions').outerHTML=actions(options);title.querySelectorAll('button[disabled]').forEach(b=>b.disabled=false);if(options.debugMode)title.querySelector('.top').insertAdjacentHTML('afterbegin','<span class="debug-badge">디버그 · 기록 분리</span>');title.removeAttribute('data-startup-title');title.removeAttribute('aria-busy');}else host.innerHTML=render(options);G.HonroStartup?.ready();}
G.HonroTitleMarkup={scene,actions,render,mount};
})(globalThis);

